\set ON_ERROR_STOP on
begin;
create schema test;
create table test.state(key text primary key,value jsonb);
grant usage on schema test to anon,authenticated;
grant select,insert,update on test.state to anon,authenticated;
create function test.ok(condition boolean,label text) returns void language plpgsql as $$ begin if condition is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function test.denied(statement text,label text) returns void language plpgsql as $$ begin begin execute statement; exception when others then raise notice 'PASS: % (rejected: %)',label,sqlerrm; return; end; raise exception 'FAIL: % was allowed',label; end $$;
grant execute on all functions in schema test to anon,authenticated;
insert into auth.users values('00000000-0000-0000-0000-000000000001'),('00000000-0000-0000-0000-000000000002');
insert into public.admin_users(user_id,role) values('00000000-0000-0000-0000-000000000001','teacher');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select test.denied($q$select public.assessment_results(gen_random_uuid())$q$,'unapproved Auth account cannot read assessment results');
select test.denied($q$select public.save_assessment('Hack','',array[]::uuid[],'[]')$q$,'unapproved Auth account cannot create assessment');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
insert into test.state values('questions','[{"prompt":"Quanto é 2+2?","explanation":"Somamos dois pares.","kind":"multiple_choice","points":10,"options":[{"label":"3","is_correct":false},{"label":"4","is_correct":true},{"label":"5","is_correct":false},{"label":"6","is_correct":false}]},{"prompt":"Linux é software livre?","explanation":"O kernel Linux é GPL.","kind":"true_false","points":5,"options":[{"label":"Verdadeiro","is_correct":true},{"label":"Falso","is_correct":false}]}]');
insert into test.state values('activity',to_jsonb(public.save_assessment('Avaliação educacional','Teste',array[(select id from public.classes where slug='poraque')],(select value from test.state where key='questions'),'{"allow_backtracking":false,"time_limit_seconds":300,"release_results":true}')));
insert into test.state select 'session',to_jsonb(s.id) from public.activity_sessions s where s.activity_id=(select (value#>>'{}')::uuid from test.state where key='activity');
insert into test.state select 'code',to_jsonb(s.access_code) from public.activity_sessions s where id=(select (value#>>'{}')::uuid from test.state where key='session');
select test.ok((select status='draft' and not ctf_enabled and time_limit_seconds=300 from public.activity_sessions where id=(select (value#>>'{}')::uuid from test.state where key='session')),'activity configuration persisted as a draft, without CTF conversion');
select test.ok((select count(*)=2 from public.questions),'multiple-choice and true/false questions persisted');
select test.ok((select count(*)=2 from public.questions where explanation<>''),'optional explanations persisted privately');
select test.ok((select count(*)=4 from public.question_options where question_id=(select id from public.questions where position=1)),'four alternatives remain four options');
select public.save_assessment('Avaliação editada','Teste',array[(select id from public.classes where slug='poraque')],(select value from test.state where key='questions'),'{"allow_backtracking":false,"time_limit_seconds":300,"release_results":true}',(select (value#>>'{}')::uuid from test.state where key='activity'));
select test.ok((select title='Avaliação editada' from public.activities),'draft freely editable');
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session'),'published');
set local role anon;
select test.ok(public.resolve_assessment_code((select value#>>'{}' from test.state where key='code')) ? 'error','published but unopened assessment cannot be joined by code');
select test.ok(public.public_activity((select (value#>>'{}')::uuid from test.state where key='session')) ? 'error','unopened questions are private');
set local role authenticated;
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session'),'open');
select test.denied($q$select public.save_assessment('Changed','',array[(select id from public.classes where slug='poraque')],(select value from test.state where key='questions'),'{}',(select (value#>>'{}')::uuid from test.state where key='activity'))$q$,'open activity content cannot be changed');
insert into test.state select 'correct_answers',jsonb_agg(jsonb_build_object('question_id',q.id,'option_id',o.id) order by q.position) from public.questions q join public.question_options o on o.question_id=q.id and o.is_correct where q.activity_id=(select (value#>>'{}')::uuid from test.state where key='activity');
set local role anon;
select test.ok((public.resolve_assessment_code((select lower(value#>>'{}') from test.state where key='code'))->>'session_id')::uuid=(select (value#>>'{}')::uuid from test.state where key='session'),'short access code resolves the open activity case-insensitively');
select test.ok(public.public_activity((select (value#>>'{}')::uuid from test.state where key='session'))::text not like '%is_correct%' and public.public_activity((select (value#>>'{}')::uuid from test.state where key='session'))::text not like '%explanation%','active quiz exposes neither answer keys nor explanations');
select test.denied('select * from public.question_options','anonymous cannot query raw answer key');
select test.denied('select * from public.assessment_updates','anonymous cannot subscribe to staff result notifications');
insert into test.state values('team',public.register_team((select id from public.classes where slug='poraque'),'Dupla permanente','Ana Silva','João Souza'));
insert into test.state values('other',public.register_team((select id from public.classes where slug='pitiu'),'Outra dupla','Maria Silva','José Souza'));
select test.ok((select points=0 and solved_count=0 from public.public_leaderboard where team_id=(select (value->>'team_id')::uuid from test.state where key='team')),'first team registration appears at zero in public CTF ranking');
select test.denied($q$select public.join_activity((select value->>'token' from test.state where key='other'),(select (value#>>'{}')::uuid from test.state where key='session'))$q$,'class restriction enforced by server');
insert into test.state select 'attempt',public.join_activity((select value->>'token' from test.state where key='team'),(select (value#>>'{}')::uuid from test.state where key='session'));
select test.ok((select value ? 'deadline' and value ? 'progress' from test.state where key='attempt'),'participation has server deadline and secure progress');
select public.save_attempt_progress((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt'),(select jsonb_build_object(value->0->>'question_id',value->0->>'option_id') from test.state where key='correct_answers'),1);
select test.ok(public.join_activity((select value->>'token' from test.state where key='team'),(select (value#>>'{}')::uuid from test.state where key='session'))->'progress'->>'current_question'='1','reconnection restores server-side question progress');
select test.denied($q$select public.save_attempt_progress((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt'),'{}',0)$q$,'linear quiz prevents overwriting completed questions');
select test.denied($q$select public.save_attempt_progress((select value->>'token' from test.state where key='other'),(select (value->>'attempt_id')::uuid from test.state where key='attempt'),'{}',0)$q$,'other team cannot recover progress');
select public.submit_attempt((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt'),(select value from test.state where key='correct_answers'));
select test.ok(public.submit_attempt((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt'),(select value from test.state where key='correct_answers'))->>'already_submitted'='true','network retry acknowledges committed delivery without duplicates');
select test.ok(public.team_result((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt')) ? 'error','grade cannot be disclosed while activity remains open');
select test.denied('select * from public.grades','students cannot read grades directly');
select test.denied('update public.public_leaderboard set points=999','students cannot alter CTF points');
set local role authenticated;
select test.ok((select count(*)=1 and min(points)=15 and min(max_points)=15 from public.grades),'backend computes the exact final grade');
select test.ok((select count(*)=2 from public.answers),'idempotent delivery creates only two answers');
select test.ok((select count(*)=0 from public.ctf_score_events),'assessment grades never become CTF score events');
select test.ok((select points=0 and solved_count=0 from public.public_leaderboard where team_id=(select (value->>'team_id')::uuid from test.state where key='team')),'public CTF ranking stays independent of pedagogical grades');
select test.ok((select count(*)=1 from public.assessment_updates),'results update notification persisted');
select test.ok(jsonb_array_length(public.assessment_results((select (value#>>'{}')::uuid from test.state where key='activity'))->'participants')=1,'authorized teacher sees private results, members and answers');
select test.ok(public.assessment_results((select (value#>>'{}')::uuid from test.state where key='activity'))->'question_stats'->0->>'correct'='1','per-question accuracy calculated in database');
select test.denied($q$select public.delete_assessment((select (value#>>'{}')::uuid from test.state where key='activity'))$q$,'deletion cannot erase existing responses and grades');
insert into test.state select 'revision',to_jsonb(public.duplicate_assessment((value#>>'{}')::uuid)) from test.state where key='activity';
select test.ok((select revision=2 and revision_of=(select (value#>>'{}')::uuid from test.state where key='activity') from public.activities where id=(select (value#>>'{}')::uuid from test.state where key='revision')),'duplication creates a new version without altering original');
select test.ok((select count(*)=1 from public.grades),'revision creation preserves original grade');
select public.delete_assessment((select (value#>>'{}')::uuid from test.state where key='revision'));
select test.ok(not exists(select 1 from public.activities where id=(select (value#>>'{}')::uuid from test.state where key='revision')),'unused draft can be deleted');
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session'),'closed');
set local role anon;
select test.ok(public.team_result((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='attempt'))->>'points'='15','own result available only after closure and explicit release');
select test.ok(public.team_result((select value->>'token' from test.state where key='other'),(select (value->>'attempt_id')::uuid from test.state where key='attempt')) ? 'error','released result is still private to its team');
set local role authenticated;
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session'),'open');
select public.authorize_retry((select (value->>'attempt_id')::uuid from test.state where key='attempt'));
set local role anon;
insert into test.state select 'retry',public.join_activity((select value->>'token' from test.state where key='team'),(select (value#>>'{}')::uuid from test.state where key='session'));
select test.ok((select value->>'attempt_id'<>(select value->>'attempt_id' from test.state where key='attempt') from test.state where key='retry'),'teacher may release a new attempt with a different UUID');
reset role;
update public.attempts set created_at=now()-interval '1 hour' where id=(select (value->>'attempt_id')::uuid from test.state where key='retry');
set local role anon;
select test.denied($q$select public.submit_attempt((select value->>'token' from test.state where key='team'),(select (value->>'attempt_id')::uuid from test.state where key='retry'),(select value from test.state where key='correct_answers'))$q$,'server rejects submissions after the configured timer');
set local role authenticated;
select public.authorize_retry((select (value->>'attempt_id')::uuid from test.state where key='retry'));
set local role anon;
insert into test.state select 'retry2',public.join_activity((select value->>'token' from test.state where key='team'),(select (value#>>'{}')::uuid from test.state where key='session'));
select test.ok((select value->>'attempt_id'<>(select value->>'attempt_id' from test.state where key='retry') from test.state where key='retry2'),'expired participation can be replaced by teacher without fake grades');
set local role authenticated;
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session'),'closed');
select public.transition_assessment((select (value#>>'{}')::uuid from test.state where key='session'),'archived');
select test.ok(public.public_activity((select (value#>>'{}')::uuid from test.state where key='session')) ? 'error','archived activity unavailable to anonymous visitors');
select test.ok(exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and tablename='assessment_updates'),'private dashboard updates registered in Realtime');
select test.ok((select count(*)=2 from public.teams),'all assessments use the original permanent team registry');
set constraints all immediate;
rollback;
